import{_ as a,o as i,c as t,a2 as e}from"./chunks/framework.CdTmk4Xw.js";const k=JSON.parse('{"title":"贡献指南","description":"","frontmatter":{"editLink":true},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md"}'),n={name:"contributing.md"};function d(p,s,l,h,o,c){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="贡献指南" tabindex="-1">贡献指南 <a class="header-anchor" href="#贡献指南" aria-label="Permalink to &quot;贡献指南&quot;">​</a></h1><p>先阅读<a href="https://github.com/xw7qwq/.github/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">组织贡献规范</a>。修改前先确定目标分支：算法代码以 <code>main</code> 为基线，文档以 <code>docs/project-guide</code> 为基线，网站以 <code>gh-pages</code> 为基线。分支职责和同步见<a href="./maintenance.html">维护流程</a>。</p><h2 id="一次变更" tabindex="-1">一次变更 <a class="header-anchor" href="#一次变更" aria-label="Permalink to &quot;一次变更&quot;">​</a></h2><ol><li>检查 <code>git status --short --branch</code>，保留已有未提交工作。</li><li>从对应基线建立描述清楚的工作分支，例如 <code>fix/cf-1000-e</code> 或 <code>docs/update-tooling</code>。</li><li>按<a href="./conventions.html">代码与归档规范</a>修改，尽量让一次提交只承担一个目的。</li><li>新文件按路径纳入 Git 跟踪，完成下表中与修改相关的检查，再查看暂存差异。</li><li>明确说明改动原因和验证范围，推送工作分支后向对应目标发起 PR，检查通过后合并。</li><li>确认来源提交已包含于目标分支后删除短期工作分支；保留 <code>main</code>、<code>docs/project-guide</code>、<code>gh-pages</code> 三个长期分支。</li></ol><table tabindex="0"><thead><tr><th>修改类型</th><th>提交前证据</th></tr></thead><tbody><tr><td>单题算法</td><td>单独编译，列出样例/边界/反例结果；AC 需要 OJ 记录</td></tr><tr><td>模板</td><td>最小调用程序和边界验证，说明接口是否变化</td></tr><tr><td>重命名或移动</td><td>来源映射可追踪，CPH 路径规则与 Pages 收录规则核对</td></tr><tr><td>归档工具或导入源码</td><td>离线归档测试与只读来源审计，见下方命令</td></tr><tr><td>文档</td><td>文档检查、API 契约检查与构建，见<a href="./maintenance.html">维护流程</a></td></tr><tr><td>网站</td><td>按<a href="./pages.html">网站维护</a>验证资源、快照和相关交互</td></tr></tbody></table><p>代码分支暂未包含文档检查脚本时，只运行该分支可用的相关检查；需要更新文档时在文档分支进行同步。归档测试和完整性审计在仓库根目录执行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unittest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/tests</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;test_archive_*.py&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/archive_verify.py</span></span></code></pre></div><p><code>archive</code> 检查核对工具行为与有来源收据的源码完整性，不执行算法，也不证明算法 AC。归档工具只读写本地文件，不自动提交或推送 Git；新增源码通过 <code>sync/</code> 等短期分支的 PR 合入 <code>main</code>，不覆盖既有源码。操作与来源收据格式见<a href="https://github.com/xw7qwq/codeflare/blob/docs/project-guide/scripts/README.md" target="_blank" rel="noreferrer">归档工具说明</a>。</p><p>人工修改都通过 PR；文档发布工作流仍直接更新 <code>gh-pages/docs/</code>。这是生成目录，不能手工修改，也不把 <code>gh-pages</code> 整体合入其他分支。</p><h2 id="提交信息" tabindex="-1">提交信息 <a class="header-anchor" href="#提交信息" aria-label="Permalink to &quot;提交信息&quot;">​</a></h2><p>采用 <code>类型(范围): 具体动作</code>，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fix(codeforces): handle disconnected graph in 1000E</span></span>
<span class="line"><span>feat(atcoder): add abc231 A solution</span></span>
<span class="line"><span>docs(tooling): explain local relay configuration</span></span>
<span class="line"><span>refactor(layout): move verified source paths</span></span></code></pre></div><p>常用类型为 <code>feat</code>、<code>fix</code>、<code>refactor</code>、<code>docs</code>、<code>chore</code>。正文补充必要的动机、来源和测试结果，不把“编译成功”写成“全部通过”。</p><p>按文件暂存并审阅，以下是仅修改 README 的例子：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> README.md</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;docs(readme): clarify repository navigation&quot;</span></span></code></pre></div><h2 id="评审说明" tabindex="-1">评审说明 <a class="header-anchor" href="#评审说明" aria-label="Permalink to &quot;评审说明&quot;">​</a></h2><p>使用下面的信息即可，不必为简单修改填写长篇报告：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原因：原有行为或缺失信息。</span></span>
<span class="line"><span>变更：修改的文件与结果。</span></span>
<span class="line"><span>验证：实际运行的命令、样例及其结果。</span></span>
<span class="line"><span>限制：尚未验证的范围；若无则省略。</span></span></code></pre></div><p>讨论算法时提供题目链接、最小反例和预期输出。涉及第三方代码时保留来源及适用许可；本仓库目前未声明统一许可证，不自动为已有代码添加授权。</p>`,19)])])}const g=a(n,[["render",d]]);export{k as __pageData,g as default};
